phase1.code:
use std::thread;
use std::time::Duration;

// ---- Basic thread ----
fn main() {
    println!("=== Threads in Rust ===");

    // ---- Spawning a thread ----
    let handle = thread::spawn(|| {
        for i in 1..=5 {
            println!("Thread: {}", i);
            thread::sleep(Duration::from_millis(100));
        }
    });

    // ---- Main thread ----
    for i in 1..=3 {
        println!("Main: {}", i);
        thread::sleep(Duration::from_millis(50));
    }

    // ---- Wait for thread to finish ----
    handle.join().unwrap();
    println!("Thread joined!");

    // ---- Thread with move ----
    let data = String::from("Hello from thread");
    let handle2 = thread::spawn(move || {
        println!("{}", data);
        // data is moved into the thread
    });
    handle2.join().unwrap();

    // ---- Multiple threads ----
    let mut handles = vec![];

    for i in 0..5 {
        let handle = thread::spawn(move || {
            println!("Thread {} is running", i);
            thread::sleep(Duration::from_millis(100));
            println!("Thread {} finished", i);
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    // ---- Thread with return value ----
    let handle3 = thread::spawn(|| {
        let sum: i32 = (1..=10).sum();
        sum
    });

    let result = handle3.join().unwrap();
    println!("Result from thread: {}", result);

    // ---- Thread panics ----
    let handle4 = thread::spawn(|| {
        panic!("Something went wrong in the thread!");
    });

    let result4 = handle4.join();
    match result4 {
        Ok(_) => println!("Thread succeeded"),
        Err(e) => println!("Thread panicked: {:?}", e),
    }

    // ---- Thread IDs ----
    let handle5 = thread::spawn(|| {
        println!("Thread ID: {:?}", thread::current().id());
    });
    handle5.join().unwrap();

    println!("Main thread ID: {:?}", thread::current().id());
}

phase2.brokenCode:
fn main() {
    let data = String::from("Hello");
    let handle = thread::spawn(|| {
        println!("{}", data);  // ERROR! data doesn't live long enough
    });
    handle.join().unwrap();
}

phase2.explanation:
The thread may outlive `data`. You need to move `data` into the thread.

**The fix:**
```rust
let handle = thread::spawn(move || {
    println!("{}", data);
});
```

**Rust-chan says:**
"Use `move` to transfer ownership to the thread."
